const COL = {
  paper:   0xf3e9d2,  // washi background
  sky:     0xefe3c8,
  waveDeep:0x16324f,  // darkest indigo
  waveMid: 0x2a5d8f,  // mid blue
  waveLite:0x6f9fc4,  // light blue
  foam:    0xf6f1e4,  // white foam
  hull:    0xd8a86e,  // wood hull
  hullDark:0x8a5a33,
  fuji:    0x274b6d,  // mountain body (blue)
  fujiSnow:0xf6f1e4,
  cloud:   0xf6f1e4,
};

